from typing import List

def product_of_primes(arr: List[int]) -> int:
    """
    Returns the product of all prime numbers in `arr`.
    If there are no primes, returns 1.
    """

    def is_prime(n: int) -> bool:
        """Check if a number is prime."""
        if n < 2:
            return False
        if n in (2, 3):
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False

        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    product = 1
    for num in arr:
        if is_prime(num):
            product *= num

    return product

