def insert_and_search(strings, query):
    """
    Inserts each string from `strings` into a Trie, then searches for `query`.

    Args:
        strings (List[str]): List of lowercase alphanumeric strings.
        query (str): String to search for.

    Returns:
        bool: True if `query` is present in the Trie, False otherwise.
    """

    class TrieNode:
        __slots__ = ("children", "is_end")

        def __init__(self):
            self.children = {}      # char -> TrieNode
            self.is_end = False     # True if this node marks the end of a word

    class Trie:
        def __init__(self):
            self.root = TrieNode()

        def insert(self, word):
            node = self.root
            for ch in word:
                if ch not in node.children:
                    node.children[ch] = TrieNode()
                node = node.children[ch]
            node.is_end = True

        def search(self, word):
            node = self.root
            for ch in word:
                if ch not in node.children:
                    return False
                node = node.children[ch]
            return node.is_end

    trie = Trie()
    for s in strings:
        trie.insert(s)
    return trie.search(query)

