func ReverseWords(words []string) []string {
    reversedStrings := make([]string, len(words))
    for i, word := range words {
        reversed := ""
        for j := len(word) - 1; j >= 0; j-- {
            reversed += string(word[j])
        }
        reversedStrings[i] = reversed
    }
    return reversedStrings
}
